    starter: "PRIORITY = {'high': 0, 'medium': 1, 'low': 2}\nSTATUS = {'missing': 0, 'partial': 1}\n\ndef gap_plan(rows):\n    # sorted() keeps the original order of rows whose keys are equal.\n    return []\n",
